// Configuración centralizada de firmas de representantes legales

export interface LegalRepresentative {
  nombre: string;
  documento: string;
  empresa: string;
  nit: string;
  cargo: string;
  urlRemota: string;
  urlLocal: string;
  dataUri: string;
}

export const FIRMA_LUZ_MILA_INVERSIONES: LegalRepresentative = {
  nombre: 'LUZ MILA CIFUENTES RUIZ',
  documento: '40.218.044 de Villavicencio',
  empresa: 'INVERSIONES INGENIERIA GC S.A.S',
  nit: '900.769.975-1',
  cargo: 'Representante Legal',
  urlRemota: 'https://santaisabel.co/wp-content/uploads/2026/09/luz-mila-.png',
  urlLocal: '/firmas/luz-mila.png',
  dataUri: 'data:image/png;base64,',
};

export function getLegalRepresentative(empresaNombre?: string, _tipoContrato?: string): LegalRepresentative | null {
  const normNombre = (empresaNombre || '').toUpperCase();
  // Para Inversiones Ingeniería en contratos de compraventa (o general)
  if (normNombre.includes('INVERSIONES') || normNombre.includes('SANTA ISABEL') || !empresaNombre) {
    return FIRMA_LUZ_MILA_INVERSIONES;
  }
  return null;
}
